Prediction predict_rf_sv(const float features[8])
{
    float sum = 0.0f;
    for (std::size_t tree = 0; tree < 300; ++tree)
    {
        sum += walk_tree(
            rf_sv_nodes, rf_sv_roots[tree],
            features, false);
    }
    const float probability = sum / 300.0f;
    return {static_cast<std::uint8_t>(probability >= 0.5f), probability};
}

Prediction predict_xgb_goose(const float features[6])
{
    float margin = 0.0f;
    for (std::size_t tree = 0; tree < 200; ++tree)
    {
        margin += walk_tree(
            xgb_goose_nodes, xgb_goose_roots[tree],
            features, true);
    }
    const float probability = sigmoid(margin);
    return {static_cast<std::uint8_t>(probability >= 0.5f), probability};
}

Prediction predict_xgb_sv(const float features[8])
{
    float margin = -1.46909535f;
    for (std::size_t tree = 0; tree < 300; ++tree)
    {
        margin += walk_tree(
            xgb_sv_nodes, xgb_sv_roots[tree],
            features, true);
    }
    const float probability = sigmoid(margin);
    return {static_cast<std::uint8_t>(probability >= 0.5f), probability};
}

